      "id": "observation-10",
      "status": "final",
      "code": {
        "text": "Capillary blood glucose"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueQuantity": {
        "value": 8.9,
        "unit": "mmol/L"
      },
      "note": [
        {
          "text": "Measured in rooms; non-fasting."
        }
      ]
    },
    {
      "resourceType": "Observation",
      "id": "observation-11",
      "status": "final",
      "code": {
        "text": "General appearance"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Well appearing, cooperative, converses coherently, and asks appropriate questions."
    },
    {
      "resourceType": "Observation",
      "id": "observation-12",
      "status": "final",
      "code": {
        "text": "Right pinna examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Mild erythema; tender on pinna traction and pressure over the tragus. No deformity or fluctuance. No obvious cellulitis extending beyond the periauricular region."
    },
    {
      "resourceType": "Observation",
      "id": "observation-13",
      "status": "final",
      "code": {
        "text": "Right external auditory canal examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Erythematous, oedematous, narrowed canal with moist debris and scant yellow exudate; canal remains patent."
    },
    {
      "resourceType": "Observation",
      "id": "observation-14",
      "status": "final",
      "code": {
        "text": "Right tympanic membrane examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Limited view; appears intact, with no bulging and no obvious middle-ear effusion."
    },
    {
      "resourceType": "Observation",
      "id": "observation-15",
      "status": "final",
      "code": {
        "text": "Left ear examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Mild dry scaling of the outer canal, consistent with psoriatic/seborrhoeic skin changes; no tenderness. Tympanic membrane normal."
    },
    {
      "resourceType": "Observation",
      "id": "observation-16",
      "status": "final",
      "code": {
        "text": "Mastoid examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "No mastoid tenderness or swelling."
    },
    {
      "resourceType": "Observation",
      "id": "observation-17",
      "status": "final",
      "code": {
        "text": "Neurological examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Cranial nerves II–XII grossly intact; no facial asymmetry."
    },
    {
      "resourceType": "Observation",
      "id": "observation-18",
      "status": "final",
      "code": {
        "text": "Neck examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "No significant cervical lymphadenopathy."
    },
    {
      "resourceType": "Observation",
      "id": "observation-19",
      "status": "final",
      "code": {
        "text": "Skin examination"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Mild psoriatic plaques on elbows and mild seborrhoeic dermatitis of the scalp."
    }
  ]
}

